import{_ as r,m as a,p as t,ac as l}from"./chunks/framework.B20rRf_H.js";const g=JSON.parse('{"title":"Useful Links","description":"Useful links for developing add-ons.","frontmatter":{"title":"Useful Links","mentions":["SirLich","MedicalJewel105","zheaEvyline","mark-wiemer","QuazChick","SmokeyStack","jasonjgardner","theaddonn"],"description":"Useful links for developing add-ons."},"headers":[{"level":2,"title":"Discord Servers","slug":"discord-servers","link":"#discord-servers","children":[{"level":3,"title":"General","slug":"general","link":"#general","children":[]},{"level":3,"title":"Creators & Marketplace","slug":"creators-marketplace","link":"#creators-marketplace","children":[]},{"level":3,"title":"Tools","slug":"tools","link":"#tools","children":[]},{"level":3,"title":"Commands","slug":"commands","link":"#commands","children":[]},{"level":3,"title":"Ray Tracing","slug":"ray-tracing","link":"#ray-tracing","children":[]},{"level":3,"title":"Protocol & Modding","slug":"protocol-modding","link":"#protocol-modding","children":[]}]},{"level":2,"title":"Documentation","slug":"documentation","link":"#documentation","children":[{"level":3,"title":"Getting Started","slug":"getting-started","link":"#getting-started","children":[]}]},{"level":2,"title":"Vanilla & Example Packs","slug":"vanilla-example-packs","link":"#vanilla-example-packs","children":[]},{"level":2,"title":"Editors & Desktop Tools","slug":"editors-desktop-tools","link":"#editors-desktop-tools","children":[{"level":3,"title":"Worlds & NBT","slug":"worlds-nbt","link":"#worlds-nbt","children":[]},{"level":3,"title":"Launchers & Version Switchers","slug":"launchers-version-switchers","link":"#launchers-version-switchers","children":[]}]},{"level":2,"title":"Web Tools","slug":"web-tools","link":"#web-tools","children":[]},{"level":2,"title":"Ray Tracing & Vibrant Visuals","slug":"ray-tracing-vibrant-visuals","link":"#ray-tracing-vibrant-visuals","children":[]},{"level":2,"title":"Publishing","slug":"publishing","link":"#publishing","children":[]},{"level":2,"title":"Other","slug":"other","link":"#other","children":[]}],"relativePath":"meta/useful-links.md","filePath":"meta/useful-links.md"}'),i={name:"meta/useful-links.md"};function o(n,e,s,c,d,h){return a(),t("div",null,[...e[0]||(e[0]=[l('<p>A curated list of communities, tools and documentation for Bedrock development. The most important links are marked with a ⭐.</p><p>This page is meant for free resources that still work and are actually useful when making add-ons. Paid tools, download mirrors and abandoned projects don&#39;t belong here.</p><h2 id="discord-servers" tabindex="-1">Discord Servers <a class="header-anchor" href="#discord-servers" aria-label="Permalink to &quot;Discord Servers&quot;">​</a></h2><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li>⭐ <a href="https://discord.gg/46JUdQb" target="_blank" rel="noreferrer">Bedrock Add-Ons</a>: The largest community for add-on development help.</li><li>⭐ <a href="https://discord.gg/XjV87YN" target="_blank" rel="noreferrer">Bedrock OSS</a>: Home of this wiki, Regolith and other open-source Bedrock projects.</li><li><a href="https://discord.gg/minecraft" target="_blank" rel="noreferrer">Minecraft</a>: The official Minecraft server.</li><li><a href="https://discord.gg/7fSQBdx" target="_blank" rel="noreferrer">Minecraft Education</a></li><li><a href="https://discord.gg/minecraftfeedback" target="_blank" rel="noreferrer">Minecraft Feedback</a>: The official server for feedback and discussion about upcoming changes.</li><li><a href="https://discord.gg/rpCyfKV" target="_blank" rel="noreferrer">Mojira</a>: Community around the Minecraft bug tracker.</li></ul><h3 id="creators-marketplace" tabindex="-1">Creators &amp; Marketplace <a class="header-anchor" href="#creators-marketplace" aria-label="Permalink to &quot;Creators &amp; Marketplace&quot;">​</a></h3><ul><li><a href="https://discord.gg/BfR7Z3T" target="_blank" rel="noreferrer">Skill Share for Minecraft Creators</a>: For creators to share skills and knowledge.</li><li><a href="https://discord.gg/XA99e2Yp77" target="_blank" rel="noreferrer">UGC Creators</a>: For people making content on UGC platforms, including the Marketplace.</li></ul><h3 id="tools" tabindex="-1">Tools <a class="header-anchor" href="#tools" aria-label="Permalink to &quot;Tools&quot;">​</a></h3><ul><li>⭐ <a href="https://discord.gg/blockbench" target="_blank" rel="noreferrer">Blockbench</a></li><li>⭐ <a href="https://discord.gg/NxKuWuA" target="_blank" rel="noreferrer">bridge.</a></li><li><a href="https://discord.gg/W9d78Z8AvM" target="_blank" rel="noreferrer">Snowstorm</a></li><li><a href="https://discord.gg/dSnwqQf" target="_blank" rel="noreferrer">Amulet &amp; MCEdit</a></li></ul><h3 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h3><ul><li>⭐ <a href="https://discord.gg/QAFXFtZ" target="_blank" rel="noreferrer">Minecraft Commands</a></li><li><a href="https://discord.gg/RHU3rjp9He" target="_blank" rel="noreferrer">Bedrock Commands Community</a></li></ul><h3 id="ray-tracing" tabindex="-1">Ray Tracing <a class="header-anchor" href="#ray-tracing" aria-label="Permalink to &quot;Ray Tracing&quot;">​</a></h3><ul><li><a href="https://discord.gg/vNWc3Hh" target="_blank" rel="noreferrer">Minecraft RTX</a></li></ul><h3 id="protocol-modding" tabindex="-1">Protocol &amp; Modding <a class="header-anchor" href="#protocol-modding" aria-label="Permalink to &quot;Protocol &amp; Modding&quot;">​</a></h3><ul><li><a href="https://discord.gg/Cxrj9UXnDB" target="_blank" rel="noreferrer">Amethyst</a>: Client-side modding framework.</li><li><a href="https://discord.gg/VCVcrvt3JC" target="_blank" rel="noreferrer">Bedrock Crustaceans</a>: Rust projects for Bedrock, including bedrock-rs.</li><li><a href="https://discord.gg/geysermc" target="_blank" rel="noreferrer">GeyserMC</a></li><li><a href="https://discord.gg/v5R5P4vRZk" target="_blank" rel="noreferrer">LeviMC</a>: LeviLamina mod loader for servers and clients, and LeviLauncher.</li><li><a href="https://discord.gg/GsEFRM8" target="_blank" rel="noreferrer">PrismarineJS (bedrock-protocol)</a></li></ul><p>Discord servers for server software are listed on the <a href="/servers/server-software">Bedrock Server Software</a> page.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li>⭐ <a href="https://learn.microsoft.com/en-us/minecraft/creator/" target="_blank" rel="noreferrer">Minecraft Creator Documentation</a>: Official documentation by Mojang and Microsoft.</li><li>⭐ <a href="https://bedrock.dev/" target="_blank" rel="noreferrer">bedrock.dev</a>: Vanilla documentation for every version, including betas.</li><li>⭐ <a href="https://minecraft.wiki/" target="_blank" rel="noreferrer">Minecraft Wiki</a>: Community wiki, mostly useful for vanilla behavior and commands.</li><li><a href="https://jaylydev.github.io/scriptapi-docs/" target="_blank" rel="noreferrer">Script API Docs (JaylyDev)</a>: Script API reference with examples and version history.</li><li><a href="https://mojang.github.io/bedrock-protocol-docs/" target="_blank" rel="noreferrer">Bedrock Protocol Docs</a> (<a href="https://github.com/Mojang/bedrock-protocol-docs" target="_blank" rel="noreferrer">GitHub</a>): Official network protocol documentation.</li><li><a href="https://gist.github.com/destruc7i0n/ea1a6a7f97f0986d9326c58246f96fa3" target="_blank" rel="noreferrer">Documentation Graveyard</a>: Components that have been removed from the game.</li></ul><h3 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h3><ul><li><a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/gettingstarted" target="_blank" rel="noreferrer">Getting Started with Add-On Development</a>: Walks you through making your first resource and behavior pack.</li><li><a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/molang/introduction" target="_blank" rel="noreferrer">An Introduction to Molang</a></li><li><a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/scriptinggettingstarted" target="_blank" rel="noreferrer">Getting Started with Scripting</a></li><li><a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/gametestgettingstarted" target="_blank" rel="noreferrer">Introduction to the GameTest Framework</a></li><li><a href="https://learn.microsoft.com/en-us/minecraft/creator/scriptapi/minecraft/server/minecraft-server" target="_blank" rel="noreferrer"><code class="shiki"><span>@minecraft/server</span></code> Reference</a></li><li><a href="https://minecraft.wiki/w/Commands#List_and_summary_of_commands" target="_blank" rel="noreferrer">List of Commands (Minecraft Wiki)</a></li></ul><h2 id="vanilla-example-packs" tabindex="-1">Vanilla &amp; Example Packs <a class="header-anchor" href="#vanilla-example-packs" aria-label="Permalink to &quot;Vanilla &amp; Example Packs&quot;">​</a></h2><p>Published by Mojang:</p><ul><li>⭐ <a href="https://github.com/Mojang/bedrock-samples" target="_blank" rel="noreferrer">bedrock-samples</a>: Vanilla resource and behavior packs, including previews, with full history.</li><li><a href="https://aka.ms/resourcepacktemplate" target="_blank" rel="noreferrer">Vanilla Resource Pack</a> / <a href="https://aka.ms/behaviorpacktemplate" target="_blank" rel="noreferrer">Behavior Pack</a></li><li><a href="https://aka.ms/MinecraftBetaResources" target="_blank" rel="noreferrer">Vanilla Resource Pack (Beta)</a> / <a href="https://aka.ms/MinecraftBetaBehaviors" target="_blank" rel="noreferrer">Behavior Pack (Beta)</a></li><li><a href="https://github.com/microsoft/minecraft-scripting-samples" target="_blank" rel="noreferrer">Script API Samples</a></li><li><a href="https://bedrock.dev/packs" target="_blank" rel="noreferrer">Pack Archive (older versions)</a></li></ul><p>Published by the community:</p><ul><li><a href="https://github.com/Bedrock-OSS/bedrock-examples" target="_blank" rel="noreferrer">bedrock-examples</a>: Example packs for the pages on this wiki.</li><li><a href="https://bedrockcommands.org/resources/" target="_blank" rel="noreferrer">Function Pack Templates</a></li></ul><h2 id="editors-desktop-tools" tabindex="-1">Editors &amp; Desktop Tools <a class="header-anchor" href="#editors-desktop-tools" aria-label="Permalink to &quot;Editors &amp; Desktop Tools&quot;">​</a></h2><ul><li>⭐ <a href="https://code.visualstudio.com/" target="_blank" rel="noreferrer">Visual Studio Code</a><ul><li><a href="https://marketplace.visualstudio.com/items?itemName=BlockceptionLtd.blockceptionvscodeminecraftbedrockdevelopmentextension" target="_blank" rel="noreferrer">Blockception&#39;s Minecraft Bedrock Development</a>: Validation and completions for add-on files.</li><li><a href="https://marketplace.visualstudio.com/items?itemName=mojang-studios.minecraft-debugger" target="_blank" rel="noreferrer">Minecraft Bedrock Debugger</a>: Official debugger for the Script API.</li></ul></li><li>⭐ <a href="https://bridge-core.app/" target="_blank" rel="noreferrer">bridge.</a>: Add-on editor that runs in the browser or as an app.</li><li>⭐ <a href="https://blockbench.net/" target="_blank" rel="noreferrer">Blockbench</a>: Modeling, texturing and animation.</li><li>⭐ <a href="https://github.com/Bedrock-OSS/regolith" target="_blank" rel="noreferrer">Regolith</a>: Build tool for add-ons with a filter system.</li><li><a href="https://github.com/Nusiq/mcblend" target="_blank" rel="noreferrer">Mcblend</a>: Blender add-on for Bedrock models and animations.</li></ul><h3 id="worlds-nbt" tabindex="-1">Worlds &amp; NBT <a class="header-anchor" href="#worlds-nbt" aria-label="Permalink to &quot;Worlds &amp; NBT&quot;">​</a></h3><ul><li><a href="https://www.amuletmc.com/" target="_blank" rel="noreferrer">Amulet</a>: World editor.</li><li><a href="https://chunker.app/" target="_blank" rel="noreferrer">Chunker</a>: Converts worlds between Java and Bedrock, and between versions.</li><li><a href="https://github.com/bedrock-dev/BedrockMap" target="_blank" rel="noreferrer">BedrockMap</a>: World viewer and NBT editor.</li><li><a href="https://github.com/8Crafter-Studios/Bedrock-World-Editor" target="_blank" rel="noreferrer">Bedrock World Editor</a>: NBT and LevelDB editor.</li><li><a href="https://github.com/tryashtar/nbt-studio" target="_blank" rel="noreferrer">NBT Studio</a>: NBT editor with support for Bedrock files.</li></ul><h3 id="launchers-version-switchers" tabindex="-1">Launchers &amp; Version Switchers <a class="header-anchor" href="#launchers-version-switchers" aria-label="Permalink to &quot;Launchers &amp; Version Switchers&quot;">​</a></h3><ul><li><a href="https://bedrocklauncher.github.io/" target="_blank" rel="noreferrer">BedrockLauncher</a> (Windows)</li><li><a href="https://levilauncher.levimc.org/" target="_blank" rel="noreferrer">LeviLauncher</a> (Windows) / <a href="https://levilaunchroid.levimc.org/" target="_blank" rel="noreferrer">LeviLaunchroid</a> (Android)</li><li><a href="https://minecraft-linux.github.io/" target="_blank" rel="noreferrer">mcpelauncher</a> (Linux &amp; macOS)</li></ul><h2 id="web-tools" tabindex="-1">Web Tools <a class="header-anchor" href="#web-tools" aria-label="Permalink to &quot;Web Tools&quot;">​</a></h2><ul><li>⭐ <a href="https://mctools.dev/" target="_blank" rel="noreferrer">Minecraft Creator Tools (mctools.dev)</a>: Official tool for creating, validating and inspecting projects.</li><li>⭐ <a href="https://jannisx11.github.io/snowstorm/" target="_blank" rel="noreferrer">Snowstorm</a>: Particle editor.</li><li>⭐ <a href="https://mcbe-essentials.github.io/" target="_blank" rel="noreferrer">MCBE Essentials</a>: Collection of editors, including: <ul><li><a href="https://mcbe-essentials.github.io/structure-editor/" target="_blank" rel="noreferrer">Structure Editor</a> and <a href="https://mcbe-essentials.github.io/structure-editor/loot-tabler" target="_blank" rel="noreferrer">Loot Tabler</a></li><li><a href="https://mcbe-essentials.github.io/structure-to-function/" target="_blank" rel="noreferrer">Structure to Function</a></li><li><a href="https://mcbe-essentials.github.io/dialogue-editor/" target="_blank" rel="noreferrer">Dialogue Editor</a></li><li><a href="https://mcbe-essentials.github.io/trade-table-editor/" target="_blank" rel="noreferrer">Trade Table Editor</a></li><li><a href="https://mcbe-essentials.github.io/selector-generator/" target="_blank" rel="noreferrer">Selector Generator</a></li><li><a href="https://mcbe-essentials.github.io/instant-pack/" target="_blank" rel="noreferrer">Instant Pack</a> and <a href="https://mcbe-essentials.github.io/world-packager/" target="_blank" rel="noreferrer">World Packager</a></li></ul></li><li><a href="https://bedrock-oss.github.io/bedrock-loot-gen/" target="_blank" rel="noreferrer">Loot Table Generator</a></li><li><a href="https://crafting.thedestruc7i0n.ca/" target="_blank" rel="noreferrer">Crafting Recipe Generator</a></li><li><a href="https://tools.pixelpoly.co/manifest-generator" target="_blank" rel="noreferrer">Manifest Generator</a></li><li><a href="https://stirante.com/behavior" target="_blank" rel="noreferrer">behavior-builder</a> / <a href="https://stirante.com/controller" target="_blank" rel="noreferrer">controller-builder</a>: Visual editors for behaviors and animation controllers.</li><li><a href="https://bridge-core.github.io/molang-playground/" target="_blank" rel="noreferrer">Molang Playground</a></li><li><a href="https://jannisx11.github.io/molang-grapher/" target="_blank" rel="noreferrer">Molang Grapher</a></li><li><a href="https://nhanaz.github.io/glyph/" target="_blank" rel="noreferrer">Glyph Tools</a></li><li><a href="https://minato.beyondbedrock.org/web-apps/textures-to-glyph/" target="_blank" rel="noreferrer">Textures to Glyph</a></li><li><a href="https://minato.beyondbedrock.org/web-apps/9slice/" target="_blank" rel="noreferrer">Nine Slice Visualiser</a>: Preview nine-slice textures for JSON UI.</li><li><a href="https://www.uuidgenerator.net/version4" target="_blank" rel="noreferrer">UUID v4 Generator</a></li></ul><h2 id="ray-tracing-vibrant-visuals" tabindex="-1">Ray Tracing &amp; Vibrant Visuals <a class="header-anchor" href="#ray-tracing-vibrant-visuals" aria-label="Permalink to &quot;Ray Tracing &amp; Vibrant Visuals&quot;">​</a></h2><ul><li>⭐ <a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/vibrantvisuals/" target="_blank" rel="noreferrer">Vibrant Visuals Documentation</a></li><li>⭐ <a href="https://learn.microsoft.com/en-us/minecraft/creator/documents/rtxgettingstarted" target="_blank" rel="noreferrer">Getting Started with Ray Tracing</a></li><li><a href="https://help.minecraft.net/hc/en-us/articles/4408865164173-Minecraft-with-Ray-Tracing-and-Advanced-Graphics-FAQ" target="_blank" rel="noreferrer">Ray Tracing FAQ</a></li><li><a href="https://github.com/jasonjgardner/painter-plugin-texture-set-json" target="_blank" rel="noreferrer"><code class="shiki"><span>.texture_set.json</span></code> plugin for Substance 3D Painter</a></li></ul><h2 id="publishing" tabindex="-1">Publishing <a class="header-anchor" href="#publishing" aria-label="Permalink to &quot;Publishing&quot;">​</a></h2><ul><li>⭐ <a href="https://www.minecraft.net/marketplace" target="_blank" rel="noreferrer">Minecraft Marketplace</a></li><li>⭐ <a href="https://www.curseforge.com/minecraft-bedrock" target="_blank" rel="noreferrer">CurseForge</a></li><li>⭐ <a href="https://mcpedl.com/" target="_blank" rel="noreferrer">MCPEDL</a></li><li>⭐ <a href="https://www.bucketofcrabs.net/" target="_blank" rel="noreferrer">Bucket of Crabs</a>: Job board for Marketplace work.</li><li><a href="https://bedrockexplorer.com/partners" target="_blank" rel="noreferrer">Marketplace Creators (Bedrock Explorer)</a>: Unofficial list of Marketplace partners.</li><li><a href="https://mcmarketstats.miste.fr/globalStats/" target="_blank" rel="noreferrer">Marketplace Stats</a>: Unofficial Marketplace statistics.</li></ul><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to &quot;Other&quot;">​</a></h2><ul><li><a href="https://www.reddit.com/r/BedrockAddons/" target="_blank" rel="noreferrer">r/BedrockAddons</a></li><li><a href="https://github.com/Pugmatt/BedrockConnect" target="_blank" rel="noreferrer">BedrockConnect</a>: Join custom servers from consoles.</li><li><a href="https://geysermc.org/" target="_blank" rel="noreferrer">Geyser</a>: Lets Bedrock players join Java servers.</li><li><a href="https://www.minecraft.net/en-us/addons" target="_blank" rel="noreferrer">Minecraft.net Add-Ons Page</a></li></ul>',39)])])}const u=r(i,[["render",o]]);export{g as __pageData,u as default};
